import threading
import time

from ute_ue.utils.param_checker import timestr_to_secs
from ute_ue.voice_call import VoiceCallDefinition

from ta_ue_plugin_android.ue.android.android_ue import AndroidUe
from ta_ue_plugin_android.ue.android.soundcard.config_loader import ConfigLoader
from ta_ue_plugin_android.ue.common.specific_keywords_list import get_soundcard_android_specific_keywords_list
from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeManagerException
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class SoundcardAndroidUe(AndroidUe):
    """
    UE type that wraps AndroidUe to be in sync with keywords used in E2E Test Automation Framework -
    Currently alive repository: https://gitlabe2.ext.net.nokia.com/TAC/DTR4/DTR4_NE_TA
    The name comes from external sound cards that are used for checking speech path.
    """
    # pylint: disable=too-many-instance-attributes, protected-access, arguments-differ, broad-except

    # Fix for Freedom customer
    STRIP_CC = True

    def __init__(self, name, serial_number, configuration, pyro_client, reservation_validator=lambda: True):
        """
        Constructs SoundcardAndroidUe, but execution should no take more than 0,2 second. (should be quick)
        See prepare_android_ue
        :param name:string friendly name of UE (no idea if anybody use it)
        :param serial_number:string serial_number of this UE, used by RPC to run method lika attach on right UE on UE PC
        :param configuration: dict - this is config of this UE, from ute_ue yaml config file
        :param pyro_client: hard to explain what it is
        :param reservation_validator: hard to explain what it is
        """
        AndroidUe.__init__(self, name, serial_number, configuration, pyro_client, reservation_validator)
        self.ue_model = None
        self._expecting_calling_ue = None
        self._my_called_voice_calls = {}
        self._my_answered_voice_calls = {}
        self.logger = LoggerAdapter4EmptyExtra(self.logger, {'area': 'SOUNDCARD_ANDROID_UE'})
        self.ussd_config = self._get_ussd_config()
        self._get_ussd_codes_from_config()
        self._get_ues_with_popup_from_config()
        if 'soundcard_name' in configuration:
            self.soundcard_name = configuration['soundcard_name']
        else:
            self.soundcard_name = None

    def _get_ussd_config(self):
        self._ussd_config_path = self.config_reader.read_ussd_config()
        self._ussd_config_loader = ConfigLoader(self._ussd_config_path)
        config = self._ussd_config_loader.load_config()
        self.logger.debug('Loaded USSD config: {}'.format(config))
        return config

    def _get_ussd_codes_from_config(self):
        self.cfu_enable = self.ussd_config['USSD_CODES']['CFU_ENABLE']
        self.cfu_disable = self.ussd_config['USSD_CODES']['CFU_DISABLE']
        self.cfb_enable = self.ussd_config['USSD_CODES']['CFB_ENABLE']
        self.cfb_disable = self.ussd_config['USSD_CODES']['CFB_DISABLE']
        self.cfna_enable = self.ussd_config['USSD_CODES']['CFNA_ENABLE']
        self.cfna_disable = self.ussd_config['USSD_CODES']['CFNA_DISABLE']
        self.cfnr_enable = self.ussd_config['USSD_CODES']['CFNR_ENABLE']
        self.cfnr_disable = self.ussd_config['USSD_CODES']['CFNR_DISABLE']
        self.boic_enable = self.ussd_config['USSD_CODES']['BOIC_ENABLE']
        self.boic_disable = self.ussd_config['USSD_CODES']['BOIC_DISABLE']
        self.baic_enable = self.ussd_config['USSD_CODES']['BAIC_ENABLE']
        self.baic_disable = self.ussd_config['USSD_CODES']['BAIC_DISABLE']
        self.baoc_enable = self.ussd_config['USSD_CODES']['BAOC_ENABLE']
        self.baoc_disable = self.ussd_config['USSD_CODES']['BAOC_DISABLE']
        self.biro_enable = self.ussd_config['USSD_CODES']['BIRO_ENABLE']
        self.biro_disable = self.ussd_config['USSD_CODES']['BIRO_DISABLE']
        self.boih_enable = self.ussd_config['USSD_CODES']['BOIH_ENABLE']
        self.boih_disable = self.ussd_config['USSD_CODES']['BOIH_DISABLE']
        self.call_waiting_enable = self.ussd_config['USSD_CODES']['CALL_WAITING_ENABLE']
        self.call_waiting_disable = self.ussd_config['USSD_CODES']['CALL_WAITING_DISABLE']

    def _get_ues_with_popup_from_config(self):
        if "UES_WITH_POPUP" in self.ussd_config:
            self.UES_WITH_POPUP = self.ussd_config['UES_WITH_POPUP']
            self.logger.debug('UEs with popup 1: {}'.format(self.UES_WITH_POPUP))
        else:
            self.logger.warning('No UES_WITH_POPUP in yml file!')
            self.UES_WITH_POPUP = {}

    def _get_specific_keywords_list(self):
        """Please do not remove or change this method. Thank you."""
        return get_soundcard_android_specific_keywords_list()

    def _log_if_over_call(self, ue):
        if ue in self._my_called_voice_calls:
            self.logger.debug('Already called to this UE')
        if ue in self._my_answered_voice_calls:
            self.logger.debug('Already answered voice call from this UE')

    def _create_expecting_incoming_voice_call(self):
        """
        Remember to call after:
        self._expecting_calling_ue = None
        :return:
        """
        if self._expecting_calling_ue is None:
            raise Exception("not defined from what Ue expecting voice call")
        self._log_if_over_call(self._expecting_calling_ue)
        vc = self.await_incoming_call(name='', timeout='30s')
        return vc

    def _forget_disconnected_voice_calls(self):
        self._my_called_voice_calls = self._dict_forget_disconnected_voice_calls(self._my_called_voice_calls)
        self._my_answered_voice_calls = self._dict_forget_disconnected_voice_calls(self._my_answered_voice_calls)

    def _dict_forget_disconnected_voice_calls(self, d):
        result = {}
        self.logger.debug('Voice Call dict = {}'.format(d))
        for ue, vc in d.iteritems():
            try:
                state = vc.get_state(return_none_if_uri_not_found=True)
            except Exception as e:  # pylint: disable=broad-except
                self.logger.debug("Failed to get voice call state: {}".format(getattr(e, 'message', str(e))))
                state = None
            if state is None or state == 'STATE_DISCONNECTED' or state == 'STATE_DISCONNECTING':
                continue
            result[ue] = vc
        return result

    def _get_answered_and_called_voice_calls(self):
        my_voice_calls = []
        my_voice_calls += self._my_answered_voice_calls.values()
        my_voice_calls += self._my_called_voice_calls.values()
        return my_voice_calls

    def _try_find_voice_call_with_ue(self, ue):
        if ue is None:
            return self._try_find_voice_call_with_ue__with_none_ue()
        if ue in self._my_answered_voice_calls:
            return self._my_answered_voice_calls[ue]
        if ue in self._my_called_voice_calls:
            return self._my_answered_voice_calls
        raise Exception("given UE (voice call identyfier) did not recognized")

    def _try_find_voice_call_with_ue__with_none_ue(self):
        my_voice_calls = self._get_answered_and_called_voice_calls()
        if len(my_voice_calls) >= 1:
            return my_voice_calls[0]
        if not my_voice_calls:
            raise Exception("No voice call on UE")
        raise Exception("More than one voice call on. Did not specified which voice call to choose.")

    def prepare_ue(self):
        """
        Method is called after contructor (__init__).
        It is allow to this method take some time to execute (like 5 seconds).
        """
        super(SoundcardAndroidUe, self).prepare_ue()
        self.ue_model = self.get_info('DEVICE_MODEL')

    def expect_call_from(self, ue):
        """
        :param ue:
        :return:
        """
        if self._expecting_calling_ue is not None:
            # raise Exception("you can expect call from only one ue")
            self.logger.debug('Here should raise ,,you can expect call from only one ue,,')
        self._expecting_calling_ue = ue

    def attach_android(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        # have to be impl
        self.attach()
        return {'return_code': True, 'return_text': "Successfully attached iPhone"}

    def detach_android(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        self.detach()
        return {'return_code': True, 'return_text': "Successfully detach"}

    def cell_id(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        return self.get_info('CELL_ID')

    def signal_strength(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        return self.get_signal_strength()

    def imsi(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        return self.get_ue_info("IMSI")

    def imei(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        return self.get_ue_info("IMEI")

    def msisdn(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        return self.phone_number

    # iphone like voice calls:

    def make_voice_call(self, ue):
        """
        :param ue:
        :return:
        """
        self._log_if_over_call(ue)
        vc = self.start_voice_call(name=ue.phone_number, definition=VoiceCallDefinition(to=ue.phone_number, dialing_timeout=0))
        self._my_called_voice_calls[ue] = vc
        return {'return_code': True, 'return_text': "Successfully called"}

    def make_voice_call_to_other(self, phone_number):
        """
        To make voice call to dummy subscriber which is not present in the TestBed.
        We will not perfom any further actions like Answer,Release and Hold Voice Call.
        :param phone_number: phone number to be called
        :return:
        """
        self.start_voice_call(name='',
                              definition=VoiceCallDefinition(to=phone_number, dialing_timeout=0))
        return {'return_code': True, 'return_text': "Successfully called"}

    def answer_incoming_voice_call(self):
        """
        Answer incoming voice call.

        :return:
        """
        vc = self._create_expecting_incoming_voice_call()
        vc.answer()
        self._my_answered_voice_calls[self._expecting_calling_ue] = vc
        self._expecting_calling_ue = None
        return {'return_code': True, 'return_text': "Successfully answer"}

    def disconnect_from_ue(self, ue_or_none):
        """
        :param ue_or_none:
        :return:
        """
        self.logger.info('Disconnecting from UE.')
        if ue_or_none is None:
            return self._disconnect_from_ue_with_none_ue()
        ue = ue_or_none
        return self._ensure_ue_voicecalls_are_disconnected(ue)

    def _ensure_ue_voicecalls_are_disconnected(self, ue):
        self.kill_all_voice_calls()
        if ue in self._my_called_voice_calls:
            self._my_called_voice_calls[ue].disconnect()
            self._forget_disconnected_voice_calls()
            del self._my_called_voice_calls[ue]
            if not self._my_called_voice_calls:
                self._expecting_calling_ue = None
            return {'return_code': True, 'return_text': 'disconnected outcomming call'}
        elif ue in self._my_answered_voice_calls:
            self._my_answered_voice_calls[ue].disconnect()
            self._forget_disconnected_voice_calls()
            del self._my_answered_voice_calls[ue]
            if not self._my_called_voice_calls:
                self._expecting_calling_ue = None
            return {'return_code': True, 'return_text': 'disconnected incomming call'}
        else:
            raise Exception("not found started call to this UE")

    def _disconnect_from_ue_with_none_ue(self):
        result = self.disconnect_all_my_voice_calls()
        self._forget_disconnected_voice_calls()
        self._my_called_voice_calls.clear()
        self._my_answered_voice_calls.clear()
        self._expecting_calling_ue = None
        return {'return_code': True, 'return_text': result}

    def speech_path_check(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        return self.speech_path_check_on_ue(self.soundcard_name, kwargs['called_subscriber'].soundcard_name)

    def merge_voice_calls(self):
        """
        Merge voice calls.

        :return:
        """
        my_voice_calls = self._get_answered_and_called_voice_calls()
        if not my_voice_calls:
            raise Exception("No voice call to merge")
        if len(my_voice_calls) == 1:
            raise Exception("No second voice call to merge")
        if len(my_voice_calls) > 2:
            raise Exception("Merging more than 2 voice calls are not supported now")
        vc1 = my_voice_calls[0]
        vc2 = my_voice_calls[1]
        vc1.merge_into_conference(vc2)
        return {'return_code': True, 'return_text': "Successfully merge call"}

    def hold_voice_call(self, ue=None):
        """
        :param ue:
        :return:
        """
        self._try_find_voice_call_with_ue(ue).hold()
        return {'return_code': True, 'return_text': "Successfully hold call"}

    def retrieve_voice_call(self, ue=None):
        """
        :param ue:
        :return:
        """
        self._try_find_voice_call_with_ue(ue).unhold()
        return {'return_code': True, 'return_text': "Successfully retrieve / unhold call"}

    def reject_call(self):
        """
        Reject an incoming call with a subscriber.
        :return:
        """
        vc = self._create_expecting_incoming_voice_call()
        try:
            vc.disconnect()
        finally:
            self._expecting_calling_ue = None
        return {'return_code': True, 'return_text': "Successfully reject call"}

    def send_sms_to(self, ue_2, text, timeout, prefix=None):
        """
        :param ue_2:
        :param text:
        :param timeout:
        :param prefix
        :return:
        """
        phone_number = ue_2.phone_number
        self.logger.info("Dialed number in SMS{} and length:{}".format(prefix, len(prefix)))
        phone_number = re.search(u'\\d{10}$', phone_number).group(0)
        self.logger.info("Before if phone no:{}".format(phone_number))
        if prefix:
            phone_number = prefix + phone_number
            self.logger.info("Inside if phone no:{}".format(phone_number))

        try:
            self.send_sms(phone_number, text)
            return {'return_code': True, 'return_text': "SMS successfully sent!"}
        except Exception as ex:
            self.logger.debug("Send SMS FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Send SMS FAILED! {}'.format(str(ex))}

    def send_sms_to_others(self, phone_number, text, timeout):
        """
        :param phone_number:
        :param text:
        :param timeout:
        :return:
        """
        self.logger.info("Inside SoundcardAndriod_ue:send_sms_to_others() To number:{}".format(phone_number))
        try:
            self.send_sms(phone_number, text)
            return {'return_code': True, 'return_text': "SMS successfully sent!"}
        except Exception as ex:
            self.logger.debug("Send SMS FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Send SMS FAILED! {}'.format(str(ex))}

    def receive_sms_from(self, ue_2, number_sms_expected, timeout):
        """
        :param ue_2:
        :param number_sms_expected:
        :param timeout:
        :return:
        """
        if isinstance(timeout, int):
            timeout = str(timeout)
        timeout = timestr_to_secs(timeout)
        current_time = time.time()
        expected_number = re.search(u'\\d{10}$', ue_2.phone_number).group(0)
        while time.time() - current_time < timeout:
            success, number, text = self._method_proxy("receive_sms")
            self.logger.info('SMS Response = {} {} {}'.format(success, number, text))
            if success:
                return self._check_if_proper_sms_was_received(number, expected_number, text, number_sms_expected)
            time.sleep(2)
        return {'return_code': False, 'return_text': 'Receive SMS failed! Timeout Reached!'}

    def _check_if_proper_sms_was_received(self, number, expected_number, text, number_sms_expected):
        if number is None:
            return {'return_code': False, 'return_text': 'Receive SMS failed! SMS not received!'}
        elif re.search(u'\\d{10}$', number).group(0) != expected_number:
            return {'return_code': False,
                    'return_text': 'Receive SMS failed! Expected sms from {}, got from {}'.format(expected_number, number)}
        elif text != str(number_sms_expected):
            return {'return_code': False,
                    'return_text': "Receive SMS failed! Expected sms '{}', got '{}'".format(number_sms_expected, text)}
        return {'return_code': True, 'return_text': "SMS received successfully"}

    def set_call_forwarding(self, mode, enable, subscriber_to):
        """
        :param mode:
        :param enable:
        :param subscriber_to:
        :return:
        """
        substo = None
        if subscriber_to:
            if self.STRIP_CC:
                # This fix is for Freedom customer
                substo = subscriber_to.phone_number[2:]  # Removes the leading '+1'
            else:
                substo = subscriber_to.phone_number[1:]  # Removes the leading '+'

        #                        Enable-code              Disable-code
        ussd_per_mode = {'CFU': (self.cfu_enable.format(substo), self.cfu_disable),
                         'CFB': (self.cfb_enable.format(substo), self.cfb_disable),
                         'CFNA': (self.cfna_enable.format(substo), self.cfna_disable),
                         'CFNR': (self.cfnr_enable.format(substo), self.cfnr_disable)}
        try:
            self.logger.info('{} is attempting to set call forwarding'.format(substo))
            self.logger.debug('USSD codes: {}'.format(ussd_per_mode))

            # Run a function to clear pop-up in a separate thread
            variant_index = 0 if enable else 1
            popup = 'enable' if variant_index == 0 else 'disable'
            popup_thread = threading.Thread(target=self.accept_popup_if_needed, args=(popup,))
            popup_thread.start()

            ussd_code = ussd_per_mode[mode][variant_index]
            self.send_ussd(ussd_code)

            return {'return_code': True, 'return_text': "Successfully set call forwarding"}
        except Exception as ex:
            self.logger.debug("Set call forwarding FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Set call forwarding FAILED! {}'.format(str(ex))}

    def accept_popup_if_needed(self, action='enable'):
        """Accept pop up on UE after sending USSD code"""
        time.sleep(3)
        if self.ue_model in self.UES_WITH_POPUP:
            x = self.UES_WITH_POPUP[self.ue_model][action][0]
            y = self.UES_WITH_POPUP[self.ue_model][action][1]
            self.logger.info('Ue in models requiring accepting popup after USSD code. Sending command adb shell input tap {} {}'.format(x, y))
            result, err = self.run_cmd_via_adb('shell', ['input', 'tap', x, y])
            self.logger.info('ADB command result = {}, error = {}'.format(result, err))

    def set_call_waiting(self, enable):
        """
        :param enable:
        :return:
        """
        try:
            self.logger.info('{} is attempting to set call waiting'.format(self.phone_number))
            if enable:
                self.send_ussd(self.call_waiting_enable)
            else:
                self.send_ussd(self.call_waiting_disable)
            return {'return_code': True, 'return_text': "Successfully set call waiting"}
        except Exception as ex:
            self.logger.debug("Set call waiting FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Set call waiting FAILED! {}'.format(str(ex))}

    def set_call_barring(self, mode, enable):
        """
        :param mode:
        :param enable:
        :return:
        """
        #                           enable     not enable
        ussd_per_mode = {'BOIC': (self.boic_enable, self.boic_disable),
                         'BAIC': (self.baic_enable, self.baic_disable),
                         'BAOC': (self.baoc_enable, self.baoc_disable),
                         'BIRO': (self.biro_enable, self.biro_disable),
                         'BOIH': (self.boih_enable, self.boih_disable)}
        try:
            self.logger.info('{} is attempting to set call barring'.format(self.phone_number))
            variant_index = 0 if enable else 1
            ussd_code = ussd_per_mode[mode][variant_index]
            self.send_ussd(ussd_code)
            return {'return_code': True, 'return_text': "Successfully set call barring"}
        except Exception as ex:
            self.logger.debug("Set call barring FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Set call barring FAILED! {}'.format(str(ex))}

    def get_call_barring(self, mode):
        """
        :param mode:
        :return:
        """
        try:
            self.logger.info('{} is attempting to get call barring'.format(self.phone_number))
            modes = {'BOIC': "*#331#", 'BAIC': "*#35#", 'BAOC': "*#33#", 'BIRO': "*#351#", 'BOIH': "*#332#"}
            self.send_ussd(modes[mode])
            return {'return_code': True, 'return_text': "Successfully got call barring"}
        except Exception as ex:
            self.logger.debug("Get call barring FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Get call barring FAILED! {}'.format(str(ex))}

    def get_call_forwarding(self, mode):
        """
        :param mode:
        :return:
        """
        try:
            self.logger.info('{} is attempting to get call forwarding'.format(self.phone_number))
            modes = {'CFU': "*#21#", 'CFB': "*#67#", 'CFNA': "*#61#", 'CFNR': "*#62#", 'ALL': "##004#"}
            self.send_ussd(modes[mode])
            return {'return_code': True, 'return_text': "Successfully get call forwarding"}
        except Exception as ex:
            self.logger.debug("Get call forwarding FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Get call forwarding FAILED! {}'.format(str(ex))}

    def get_call_waiting(self):
        """
        get_call_waiting

        :return:
        """
        try:
            self.logger.info('{} is attempting to get call waiting'.format(self.phone_number))
            self.send_ussd("*#43#")
            return {'return_code': True, 'return_text': "Successfully got call waiting"}
        except Exception as ex:
            self.logger.debug("Get call waiting FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Get call waiting FAILED! {}'.format(str(ex))}

    def send_ussd(self, ussd):
        """
        :param ussd:
        :return:
        """
        try:
            self.logger.info('{} is attempting to send USSD {}'.format(self.phone_number, ussd))
            self.start_voice_call(name='', definition=VoiceCallDefinition(to=ussd, dialing_timeout=0))
            return {'return_code': True, 'return_text': "USSD successfully sent"}
        except Exception as ex:
            self.logger.debug("Sending USSD FAILED! {}".format(getattr(ex, 'message', str(ex))))
            return {'return_code': False, 'return_text': 'Sending USSD FAILED! {}'.format(str(ex))}

    def set_network_mode(self, network_mode):
        """
        :param network_mode:
        :return:
        """
        try:
            return self._check_network_mode_and_change_it(network_mode)
        except Exception as ex:
            self.logger.debug("Set network mode FAILED, please check if the Xposed Framework is properly installed! {}".format(
                getattr(ex, 'message', str(ex))))
            return {'return_code': False,
                    'return_text': 'Set network mode FAILED, please check if the Xposed Framework is properly installed! {}'.format(str(ex))}

    def _check_network_mode_and_change_it(self, network_mode):
        if network_mode == "2G" or network_mode == "GSM":
            self.change_network_mode("GSM_only")
            return {'return_code': True, 'return_text': "Successfully enabled 2G"}
        elif network_mode == "3G" or network_mode == "UMTS":
            self.change_network_mode("WCDMA_only")
            return {'return_code': True, 'return_text': "Successfully enabled 3G"}
        elif network_mode == "LTE" or network_mode == "4G":
            self.change_network_mode("LTE_only")
            return {'return_code': True, 'return_text': "Successfully enabled 4G"}
        elif network_mode.upper() == "AUTO":
            self.change_network_mode("LTE_GSM_WCDMA")
            return {'return_code': True, 'return_text': "Successfully enabled Automatic"}
        return {'return_code': True, 'return_text': "Network does not exist!"}

    def enable_wifi(self, enable):
        """
        :param enable:
        :return:
        """
        try:
            self.logger.info('{} is attempting to enable/disable wifi'.format(self.phone_number))
            if not enable:
                self.turn_wifi_off()
            else:
                self.turn_wifi_on()
            return {'return_code': True, 'return_text': "Enable/disable wifi was successful!"}
        except Exception as ex:
            return {'return_code': False, 'return_text': 'Enable/Disable wifi FAILED! {}'.format(str(ex))}

    def reboot(self):
        """
        Make reboot.

        :return:
        """
        try:
            self.logger.info('{} is attempting to reboot'.format(self.phone_number))
            self.ue_reboot_and_wait_until_it_boots()
            return {'return_code': True, 'return_text': 'Rebooted phone Successfully'}
        except Exception as ex:
            return {'return_code': False, 'return_text': 'Reboot FAILED! {}'.format(str(ex))}

    def record(self, duration, scope):
        """
        :param duration:
        :param scope:
        :return:
        """
        return self.record_on_ue(duration, scope, self.soundcard_name)

    def get_radio_access_technology(self):
        """
        Get RAT.

        :return:
        """
        try:
            rat = self.get_current_technology_on_uepc()
            if rat:
                self.logger.info("Radio Access Technology was %s.", rat)
            else:
                self.logger.Error("Failed to retrieve Radio Access Technology. Found %s", rat)

            # if rat not in RadioAccessTechnology.valueMap.values():
            #     self.logger.Fail("Unknown Radio Access Technology. Found %s", rat)
            #     return {'return_code': False, 'return_text': 'FAIL - Failed to find in the default connection types'}

            rat_dict = {'2G': '2G', 'GSM': '2G', 'UTRAN': 'UTRAN',
                        'CDMA': '3G', 'WCDMA': '3G', '3G': '3G', 'HSDPA': '3G',
                        'HRPD': 'HRPD', '4G': '4G', 'LTE': '4G',
                        'Unknown': 'Unknown', '-1': 'Unknown'}
            if rat in rat_dict:
                current_rat = rat_dict[rat]
                self.logger.info("Matched Radio Access Technology {}.".format(current_rat))
            else:
                self.logger.Error("Did not match any known Radio Access Technology definitions.")
                return {'return_code': False, 'return_text': 'FAIL - to get Radio Access Technology'}
            return {'return_code': True, 'return_text': current_rat}

        except Exception as ex:
            self.logger.info('FAIL -  Failed attempt to get Radio Access Technology! {}'.format(str(ex)))
            return {'return_code': False, 'return_text': 'FAIL -  Failed attempt to get Radio Access Technology! {}'.format(str(ex))}

    def shutdown(self):
        """Shutdown"""
        self.logger.debug('Shutting down the UE.')
        self.logger.debug('Killing all voice calls on UE')
        self.kill_all_voice_calls()
        self._my_called_voice_calls = {}
        self._my_answered_voice_calls = {}
        self._method_proxy('unreserve_ue')
        self.logger.debug('Ue was shut down. Should be ready to use again now')


class CommandNotSupportedException(UeManagerException):
    """Exception"""
    pass
